<?php
require_once __DIR__ . '/../includes/layout.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){ $extension=one('SELECT * FROM extensions WHERE id=?',[(int)$_POST['id']]); $status=$_POST['status']; if($extension){ if($status==='approved'){ execute('UPDATE borrowings SET due_date=datetime(due_date,"+7 days"),renew_count=renew_count+1,status="active" WHERE id=?',[$extension['borrowing_id']]); execute('UPDATE extensions SET status=?,admin_note=?,reviewed_at=CURRENT_TIMESTAMP,new_due_date=(SELECT due_date FROM borrowings WHERE id=?) WHERE id=?',[$status,trim($_POST['admin_note']??''),$extension['borrowing_id'],$extension['id']]); } else execute('UPDATE extensions SET status=?,admin_note=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=?',[$status,trim($_POST['admin_note']??''),$extension['id']]); flash('Permintaan perpanjangan ditinjau.'); } redirect('admin/extensions.php'); }
$data=rows('SELECT e.*,u.name,u.member_id,b.title,br.due_date,br.renew_count FROM extensions e JOIN users u ON u.id=e.user_id JOIN borrowings br ON br.id=e.borrowing_id JOIN books b ON b.id=br.book_id ORDER BY e.requested_at DESC'); page_head('Perpanjangan',true); admin_heading('Perpanjangan','Tinjau permintaan perpanjangan masa pinjam');
?><section class="card table-card"><table><thead><tr><th>Anggota</th><th>Buku</th><th>Jatuh tempo</th><th>Perpanjangan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($data as $row): ?><tr><td><?=e($row['name'])?><br><small class="muted"><?=e($row['member_id'])?></small></td><td><?=e($row['title'])?></td><td><?=date_id($row['due_date'])?></td><td><?=e($row['renew_count'])?>x</td><td><?=status_badge($row['status'])?></td><td><?php if($row['status']==='pending'): ?><form method="post" class="actions"><input type="hidden" name="id" value="<?=$row['id']?>"><input name="admin_note" placeholder="Catatan"><button name="status" value="approved" class="success">Setujui</button><button name="status" value="rejected" class="danger">Tolak</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section><?php page_foot(true); ?>
